using System.Collections.Immutable;
using System.Text.Json;
using Game.Application;
using Game.Domain;
using Game.Simulation;
namespace Game.BrowserFixtureHost;

// Synthetic repeated-circuit UI boundary fixture. Every package and debit below is generated by
// public development operations. It never writes a production campaign or grants extra credits.
internal sealed class PackageRefinementScenario
{
 private readonly object gate=new();
 private readonly DevelopmentPersonnel staff=new("synthetic-frozen-roster",0,0,0,0);
 private DevelopmentState state=null!;private ImmutableArray<CreditEntry> ledger;
 private RacePackageVersion source=null!;private EffectiveWeekend frozen=null!;
 private const string Id="synthetic-refinement",Team="team-01",Device="synthetic-device";
 private static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);
 public PackageRefinementScenario()=>Reset();
 private void Reset()
 {
  ledger=[new("start",Team,100,"starting-credit")];
  var risk=DevelopmentRiskControls.Only("normal");var quote=PackageDevelopment.QuoteRich("downforce",staff,risk);
  var purchase=PermanentDevelopment.Open("synthetic-purchase","one","two",[Team]);
  purchase=PermanentDevelopment.Edit(purchase,Team,new(Guid.NewGuid().ToString(),purchase.Id,1,"PackageCreation","downforce",quote.Id),staff,risk:risk);
  var paid=PermanentDevelopment.Commit(purchase,ledger,Team,new(Guid.NewGuid().ToString(),purchase.Id,purchase.Revision,1,quote.Id),staff);ledger=paid.Ledger;
  state=PermanentDevelopment.Close(new(PermanentDevelopment.Version,[paid.State],new string('8',64)),purchase.Id,["one","two","three"]);
  source=state.PackageOutcomes.Single().Package!;
  var preset=Preset("track-monza");var library=RacePackages.Complete(preset,state.PackageOutcomes);
  frozen=WeekendPreparation.Prepare(RacePackages.Select(library,new(source.PackageId,1)),6,new());
  state=state with{Opportunities=state.Opportunities.Add(PermanentDevelopment.Open("synthetic-refinement-op","two","three",[Team]))};
 }
 private static WeekendPreset Preset(string track){var preset=WeekendPresetCatalog.Open(track);return preset with{Cars=preset.Cars.Select(c=>c with{TeamId=Team}).ToImmutableArray()};}
 private DevelopmentOpportunity Opportunity=>state.Opportunities[^1];
 public object Run(string operation,JsonElement command)
 {
  lock(gate)
  {
   if(operation=="reset")Reset();
   else if(operation=="draft")
   {
    var edit=command.Deserialize<DevelopmentEdit>(Json)??throw new ArgumentException("Supply the actual UI draft command.");
    var next=PermanentDevelopment.Edit(Opportunity,Team,edit,staff,risk:DevelopmentRiskControls.Only("normal"),library:[source]);
    state=state with{Opportunities=state.Opportunities.SetItem(state.Opportunities.Length-1,next)};
   }
   else if(operation=="commit")
   {
    var input=command.Deserialize<DevelopmentCommit>(Json)??throw new ArgumentException("Supply the actual UI commitment.");
    var paid=PermanentDevelopment.Commit(Opportunity,ledger,Team,input,staff);ledger=paid.Ledger;
    state=state with{Opportunities=state.Opportunities.SetItem(state.Opportunities.Length-1,paid.State)};
   }
   else if(operation=="close")state=PermanentDevelopment.Close(state,Opportunity.Id,["one","two","three"]);
   // The fixture restores the concrete contract after every command, simulating process-boundary
   // serialization. Real durable adapter/restart tests remain in Game.Api.Tests.
   state=JsonSerializer.Deserialize<DevelopmentState>(JsonSerializer.Serialize(state,Json),Json)!;
   ledger=JsonSerializer.Deserialize<ImmutableArray<CreditEntry>>(JsonSerializer.Serialize(ledger,Json),Json);
   return Snapshot();
  }
 }
 private object Snapshot()
 {
  var op=Opportunity;var quotes=new[]{"strengthen","reduce-compromise","broaden-usefulness"}.Select(kind=>PackageDevelopment.QuoteRefinement(source,kind,staff,DevelopmentRiskControls.Only("normal"))).ToArray();
  var outcome=state.PackageOutcomes.FirstOrDefault(o=>o.ProjectId==op.Id+"/"+Team);
  var projects=outcome is null?Array.Empty<DevelopmentProjectSummary>():[new(outcome.ProjectId,outcome.Kind,"completed","three","Synthetic public-domain result: purchased source v1 preserved; paid refinement created immutable v2.","PackageRefinement")];
  var car=Preset("track-monza");
  var development=new DevelopmentTeamSnapshot(Id,Team,op.Id,op.Revision,1,ledger.Sum(e=>e.Credits),[],op.Drafts[Team],op.Decisions.SingleOrDefault(),
   Timing:"Synthetic repeated-circuit fixture generated by public development operations; not a supported full-calendar campaign.",Projects:projects,CurrentCar:car.Cars[0].Car.Ratings,NextCar:car.Cars[0].Car.Ratings,PolicyChoices:[],CurrentEventId:"two",NextEventId:"three",Help:new("synthetic-second","synthetic-player","Standard",false,false),OptionSpecialties:new Dictionary<string,string>{{"downforce","Aerodynamics"}},PackageOptions:[],RefinementOptions:quotes);
  var circuits=new[]{Preset("track-monza").Circuit,Preset("track-monaco").Circuit,Preset("track-monza").Circuit};
  var calendar=circuits.Select((c,i)=>new CampaignEvent(new[]{"one","two","three"}[i],i+1,c.Id,"Synthetic repeat · "+c.Name,c.Slug,c.Version,new[]{"synthetic-first","synthetic-second","synthetic-third"}[i])).ToArray();
  var team=new CampaignTeam(Team,"mclaren","McLaren",car.Cars.Select(c=>new CampaignDriver(c.Driver.Id,c.Driver.Name,c.Driver.Slug,c.EntryId,c.Driver.Version)).ToArray());
  var campaign=new CampaignSnapshot(Id,op.Revision,"event-result-committed","synthetic-domain-fixture-v1","synthetic-repeated-monza-monaco", "Synthetic public-domain fixture",calendar,[team],1,"synthetic-second",[],false,Points:ChampionshipScoring.Default,Standings:new([],[]),Results:[],NextPreparation:new("three","synthetic-third",calendar[2].TrackName,[],false),Development:new(op.Id,"two","three",op.Closed?"closed":"open",[new(Team,op.Decisions.Length>0,"manual-confirmation")],!op.Closed&&op.Decisions.Length>0,op.Revision));
  return new{campaign,development,source,frozen,library=state.PackageOutcomes.Select(o=>o.Package).ToArray(),ledger};
 }
}
internal sealed record RefinementFixtureCommand(string Operation,JsonElement Command);
internal sealed class PackageRefinementFilter(PackageRefinementScenario scenario):IStartupFilter
{
 public Action<IApplicationBuilder> Configure(Action<IApplicationBuilder> next)=>app=>
 {
  app.Use(async(context,following)=>
  {
   if(context.Request.Path=="/__test/package-refinement"&&context.Request.Method=="POST")
   {
    try{var input=await context.Request.ReadFromJsonAsync<RefinementFixtureCommand>();await context.Response.WriteAsJsonAsync(scenario.Run(input!.Operation,input.Command));}
    catch(Exception error) when(error is ArgumentException or InvalidOperationException){context.Response.StatusCode=409;await context.Response.WriteAsJsonAsync(new{message=error.Message});}
    return;
   }
   await following(context);
  });next(app);
 };
}
